        // ---- BARD: a bard picks the gentler rites (light, sleep, charm, protection, mending, travel) ----
        // Each entry borrows the mechanics of the Divine/Arcane spell of the same id, with its own unlock level and cost.
        function bardSpell(id, lvl, over) {
            const base = SPELLS.cler.concat(SPELLS.wiz).find(sp => sp.id === id);
            if (!base) throw new Error('bard spell ' + id);
            return Object.assign({}, base, { school: 'bard', lvl }, over || {});
        }
