        MONSTERS[20].rank = 2;
        const M_ROPER = 15, M_DEER = 16, M_WISP = 20;
        // the server rolls a difficulty band (0-6) from the hero's level; the species is chosen here from the terrain it walks on
        const WILD_BANDS = [[8, 9, 10], [11, 12, 13], [0, 1], [14, 2], [3], [4], [5]];
        const WILD_AFFINITY = {
            8: [41, 1], 9: [3, 2], 10: [3, 2], 11: [2, 3, 1], 12: [53, 54, 51, 52, 41], 13: [2, 55, 56, 57, 1], 0: [1, 52, 3], 1: [51, 62, 41], 14: [41, 2, 53], 2: [2, 55, 1]
        };
        function wildMonsterFor(rank, id, x, y) {
            const band = WILD_BANDS[Math.max(0, Math.min(WILD_BANDS.length - 1, rank | 0))];
            if (band.length === 1) return band[0];
            const t = getWorldTile(x, y);
            const w = band.map(i => ((WILD_AFFINITY[i] || []).includes(t) ? 4 : 1));
            let r = wfHash(id | 0, 7, 11) * w.reduce((a, b) => a + b, 0);
            for (let k = 0; k < band.length; k++) { if ((r -= w[k]) < 0) return band[k]; }
            return band[0];
        }
        // what a roamer sent by the server really is: kind 0 wandering monster (species by terrain), 1 wildlife, 2 a monster of a ruin or dungeon mouth
        function roamerSpecies(m) {
            const t = getWorldTile(m.x, m.y), h = wfHash(m.id | 0, 3, 17);
            if (m.kind === 1) {
                if (t === TILE.MOUNTAIN) return 19;                                                     // mountain goat
                if (t === TILE.SAVANNA || t === TILE.DESERT) return 17;                                 // antelope
                if (t === TILE.TAIGA || t === TILE.SNOW || t === TILE.ICE) return 18;                   // hare
                return h < 0.3 ? 18 : 16;                                                               // hare or deer
            }
            if (m.kind === 2) {
                const L = (state.overworld.lairList || [])[m.lair | 0];
                if (L && L.type === 2) return L.species;                                                 // an encampment breeds one kind of monster
                const lair = (L ? L.type === 0 : ((state.overworld.ruins || []).length > (m.lair | 0))) ? 'ruins' : 'dungeon';
                if (lair === 'ruins') {
                    const night = wfIsNight(getTimeOfDayInfo().hour);
                    if (night && m.tier >= 2 && h < 0.12) return 7;                                      // a ghost, rarely, after dark
                    return h < 0.7 ? 1 : (h < 0.85 ? 10 : 8);                                            // skeleton, bat or rat
                }
                const band = WILD_BANDS[Math.max(0, Math.min(WILD_BANDS.length - 1, m.tier | 0))];
                return band[Math.floor(h * band.length) % band.length];
            }
            return wildMonsterFor(m.tier, m.id, m.x, m.y);
        }
        const MAX_WILD_TIER = 6;       // roaming monsters and dungeon spawns stop at the Crimson Wyrm (the mimic and the ghost only appear in their own places)
