                const peak = (0.22 + Math.random() * 0.12) * level;
                const s = c.createBufferSource(); s.buffer = this.noiseWhite; s.loop = true;
                const lp = c.createBiquadFilter(); lp.type = 'lowpass'; lp.Q.value = 0.6;
                lp.frequency.setValueAtTime(380, now);
