        function icon(name, cls) {
            return `<svg class="ico ${cls || ''}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICON[name] || ICON.star}</svg>`;
        }
        function hydrateIcons(root) {
            (root || document).querySelectorAll('[data-icon]').forEach(el => { el.innerHTML = icon(el.dataset.icon, el.dataset.cls); });
        }
        const escHtml = (s) => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
        const tipAttr = (html) => `data-tip="${escHtml(html)}"`;

        const SPELL_GLYPH = {
            heal: 'heartplus', great_heal: 'heartplus', cure: 'leaf', harm: 'skull', create_food: 'bread', locate: 'compass', protection: 'shield', mass_protect: 'shield',
            repel_undead: 'sun', help: 'home', fear: 'ghost', peer: 'eye', resurrect: 'ankh', sleep_field: 'moon', charm: 'heart', mass_charm: 'heart', disable: 'target',
            slime: 'droplets', eclipse: 'eclipse', magic_arrow: 'arrow', sleep: 'moon', mass_sleep: 'moon', light: 'bulb', great_light: 'sun', poison: 'droplet',
            poison_field: 'droplet', fireball: 'flame', explosion: 'burst', curse: 'hex', conjure: 'paw', fire_field: 'flame', lightning: 'bolt', paralyze: 'lock',
            insect_swarm: 'bug', energy_field: 'grid', flame_wind: 'wind', energy_wind: 'wind', confuse: 'spiral', chain_bolt: 'chain', gate_travel: 'portal',
            kill: 'skull', wing_strike: 'feather', tremor: 'mountain', summon: 'horns', death_wind: 'wind', time_stop: 'hourglass', mass_kill: 'skull', armageddon: 'meteor',
            frag_grenade: 'burst', flash_bang: 'bulb', clockwork_turret: 'target', smoke_bomb: 'wind', robot_dog: 'paw', glue_bomb: 'lock', acid_flask: 'flask',
            robot_spider: 'bug', incendiary: 'flame', cluster_bomb: 'meteor', steam_golem: 'mountain', tesla_grenade: 'chain', gas_grenade: 'droplets',
            mortar_barrage: 'meteor', thermite: 'flame', doomsday: 'eclipse'
        };
        function spellIcon(sp, small, locked) {
            return `<span class="sp-ico${small ? ' sm' : ''}${locked ? ' lock' : ''}" style="--c:${spellRgb(sp)}">${icon(SPELL_GLYPH[sp.id] || 'sparkles')}</span>`;
        }
        const WEAPON_GLYPH = { 'Dagger': 'dagger', 'Heavy Mace': 'mace', 'Hunting Bow': 'bow', 'Musket Pistol': 'pistol', 'Broadsword': 'sword', 'Blunderbuss': 'blunder', 'Silver Halberd': 'halberd', 'Musket Rifle': 'rifle', 'Astral Blade': 'astral' };
        const HEAD_GLYPH = { wizhat: 'sparkles', circlet: 'sun', hood: 'ghost', beret: 'music', goggles: 'cog', cap: 'helmet', coif: 'mail', helm: 'helmet', greathelm: 'aegis' };
        const ARMOR_GLYPH = { 'Cloth Tunic': 'shirt', 'Leather Armor': 'vest', 'Studded Cuirass': 'vest', 'Chainmail Hauberk': 'mail', 'Steel Plate': 'helmet', 'Astral Aegis': 'aegis' };
        const CLASS_GLYPH = { Fighter: 'sword', Paladin: 'shield', Ranger: 'bow', Rogue: 'dagger', Cleric: 'ankh', Wizard: 'sparkles', Bard: 'music', Tinker: 'cog' };
        function hexRgb(h) { const n = parseInt(h.slice(1), 16); return `${(n >> 16) & 255},${(n >> 8) & 255},${n & 255}`; }
        function gearIcon(kind, base, magic) {
            const glyph = kind === 'w' ? (WEAPON_GLYPH[base.name] || 'sword') : (kind === 'h' ? (HEAD_GLYPH[base.vis] || 'helmet') : (kind === 's' ? 'shield' : (ARMOR_GLYPH[base.name] || 'shield')));
            const c = magic ? VARIANT_RGB[itemVariant(magic)] : (kind === 'w' ? '251,191,36' : (kind === 'h' ? '196,181,253' : (kind === 's' ? '244,114,182' : '103,232,249')));
            return `<span class="it-ico" style="--c:${c}">${icon(glyph)}</span>`;
        }
        function simpleIcon(glyph, rgb) { return `<span class="it-ico" style="--c:${rgb}">${icon(glyph)}</span>`; }

        // ===================== UI: TOOLTIPS =====================
        function tipBox(title, sub, rows, desc, foot, iconHtml) {
            let h = `<div class="tip-h">${iconHtml || ''}<div><div class="tip-t">${title}</div>${sub ? `<div class="tip-s">${sub}</div>` : ''}</div></div>`;
            (rows || []).forEach(r => { if (r) h += `<div class="tip-r"><span class="tip-k">${r[0]}</span><span class="tip-v"${r[2] ? ` style="color:${r[2]}"` : ''}>${r[1]}</span></div>`; });
            if (desc) h += `<div class="tip-d">${desc}</div>`;
            if (foot) h += `<div class="tip-f">${foot}</div>`;
            return h;
        }
        const CMD_TIPS = {
            enter: ['door', 'Enter / Use', 'E', 'Enter the town, castle, dungeon or Moongate you stand on; climb ladders in dungeons. In battle it confirms a spell target.'],
            auto: ['target', 'Auto-Attack', 'Q', 'Battle only: click a foe to select it, then press this to attack it with thy equipped weapon every turn. If it is out of range thy hero waits until it comes into range. Any other command stops it. Aimed spells use the selected foe too; helpful spells go to thyself while a foe is selected.'],
            cast: ['sparkles', 'Cast / Potion', 'C', 'Open the grimoire. In battle the active hero casts or drinks a potion; outside battle any caster may use healing and travel spells. Aimed spells let you pick the target.'],
            camp: ['tent', 'Camp', 'R', 'Pitch a tent and light a fire on the spot. HP and MP mend slowly (uses up one ration); the rest ends when everyone is whole, when you move, or when you press R again. Monsters keep away from the fire.'],
            ship: ['anchor', 'Board / Leave Ship', 'X', 'Board thy ship when standing beside her, or disembark onto an adjacent shore. Ship deeds are sold by harbour masters.'],
            inventory: ['backpack', 'Stats & Gear', 'I', 'Inspect heroes, equip weapons, armour and magic items, rearrange the bag by dragging, right-click a potion to drink it, and read the grimoire. Keys 1-4 switch heroes.'],
            map: ['map', 'Globe Map', 'M', 'Show the whole explored world: towns, ports, dungeons, Moongates, rivers and marshes.'],
            pass: ['hourglass', 'Wait / Pass', 'Space', 'Pause a moment (time passes by itself now), or hold position in battle.'],
            flee: ['run', 'Flee', 'F', 'Battle only: the active hero tries to escape. High DEX, standing near the left edge and few awake foes improve the odds. In a shared battle the others fight on.'],
            look: ['eye', 'Look / Inspect', 'L', 'Examine monsters, terrain, people and objects without spending time. Move the cursor with WASD, jump between targets with T, or just click a tile.'],
            zoomin: ['plus', 'Zoom In', '+', 'Zoom in on the overland map, towns or the battlefield (up to 300%). Mouse wheel works too. In battle the view follows the active hero or your spell target.'],
            zoomout: ['minus', 'Zoom Out', '-', 'Zoom back out (down to 75%) to see more of the land.'],
            music: ['music', 'Music', 'N', 'Toggle the music: a march for the overland roads, a rolling sea shanty aboard ship, a lute minuet in towns and a cold, sparse theme in dungeons. Battles switch to a combat theme.'],
            sound: ['volume', 'Sound', '', 'Toggle sound effects and ambience (surf, birds, crickets, rain, thunder, dungeon echoes...).'],
            menu: ['gear', 'Menu', 'Esc', 'Save to the server, log out, read the manual or set up audio.'],
            help: ['book', 'Manual', '?', 'The Adventurer\'s Compendium: rules, classes, magic, weather, items and more.'],
            N: ['up', 'Move North', 'W', 'Walk north. In dungeons: step forward.'], S: ['down', 'Move South', 'S', 'Walk south. In dungeons: step back.'],
            W: ['left', 'Move West', 'A', 'Walk west. In dungeons: turn left.'], E: ['right', 'Move East', 'D', 'Walk east. In dungeons: turn right.']
        };
        function cmdTip(key) {
            const c = CMD_TIPS[key];
            if (!c) return '';
            return tipBox(c[1], c[2] ? `Hotkey <span class="tip-key">${c[2]}</span>` : '', null, c[3], null, `<span class="it-ico" style="--c:251,191,36">${icon(c[0])}</span>`);
        }
        function spellTargetLabel(sp) {
            const k = spellTargetKind(sp);
            if (k === 'enemy') return sp.type === 'blast' ? `a foe you choose + ${sp.radius || 1}-tile blast` : (sp.type === 'wind' || sp.mode === 'wind' ? 'a cone towards the foe you choose' : (sp.type === 'chain' ? 'the foe you choose, then 2 more' : (typeof sp.targets === 'number' && sp.targets > 1 ? `the foe you choose + ${sp.targets - 1} near it` : 'one foe you choose')));
            if (k === 'ally') return 'one ally you choose';
            if (k === 'poisoned') return 'one poisoned ally';
            if (k === 'fallen') return 'one fallen ally';
            if (sp.type === 'protect') return 'the whole party';
            if (sp.type === 'aoe' || sp.targets === 'all' || sp.mode === 'all' || sp.type === 'armageddon') return 'every foe';
            if (sp.targets === 'undead') return 'every undead foe';
            if (sp.type === 'protect') return 'the whole party';
            return 'the party / the world';
        }
        function spellTip(hero, sp) {
            const unlock = hero ? spellUnlockLevel(hero, sp) : sp.lvl;
            const known = !hero || hero.lvl >= unlock;
            const rows = [
                ['School', `${SCHOOL_LABEL[sp.school] || 'Arcane'} • ${sp.school === 'tink' ? 'tier' : 'circle'} ${sp.circle}`],
                ['Mana', `${sp.cost} MP`, hero && hero.mp < sp.cost ? '#fb7185' : '#fbbf24'],
                ['Target', spellTargetLabel(sp)]
            ];
            if (sp.dice) {
                const extra = (hero && sp.grow) ? Math.floor(Math.max(0, hero.lvl - unlock) / sp.grow) : 0;
                rows.push(['Power', `${diceStr(sp.dice[0] + extra, sp.dice[1], sp.dice[2] || 0)}${sp.mod ? ' + ' + (sp.school === 'cler' ? 'WIS' : (sp.school === 'bard' ? 'WIS/INT' : 'INT')) : ''}${sp.grow ? ` (+1 die / ${sp.grow} lv)` : ''}`]);
            }
            if (hero && (sp.type === 'status' || sp.type === 'death' || sp.stick)) rows.push(['Save DC', `${spellDC(hero, sp)}`]);
            if (sp.power && (sp.type === 'status' || sp.type === 'field' || sp.type === 'summon' || sp.type === 'protect')) rows.push(['Lasts', `${sp.power} rounds`]);
            rows.push(['Use', sp.battle === false ? 'outside battle only' : (sp.field ? 'in battle & outside' : 'in battle')]);
            if (!known) rows.push(['Unlocks', `at level ${unlock}`, '#94a3b8']);
            return tipBox(sp.name, known ? (hero ? hero.name + "'s spell" : '') : 'not yet learned', rows, sp.desc, null, spellIcon(sp));
        }
        function plainGearTip(kind, item, hero) {
            const rows = kind === 'h'
                ? [['Armour class', item.ac ? `+${item.ac}` : 'none'], item.mp ? ['Max mana', `+${item.mp}`, '#7dd3fc'] : null, ['Value', `${item.cost} gold`]]
                : kind === 'w'
                ? [['Damage', `${item.dice} + ${item.stat === 'dex' ? 'DEX' : (item.stat === 'str' ? 'STR' : 'STR or DEX')}`], ['Reach', `${item.range} tile${item.range > 1 ? 's' : ''}`], item.atk ? ['To hit', `+${item.atk}`] : null, ['Value', `${item.cost} gold`]]
                : kind === 's'
                ? [['Armour class', `+${item.ac}`], ['Value', `${item.cost} gold`]]
                : [['Armour', armorLabel(item)], ['Value', `${item.cost} gold`]];
            rows.push(['Classes', item.classes.join(', ')]);
            return tipBox(item.name, GEAR[kind].title, rows, hero && !item.classes.includes(hero.cls) && !hero.debug ? `<span style="color:#fb7185">${hero.cls}s cannot use this.</span>` : '', null, gearIcon(kind, item, null));
        }
        // the second tooltip beside a shop / bag item: what the champion wears in that slot right now
        function equippedCompareTip(kind, hero) {
            if (!hero) return '';
            const G = GEAR[kind], mag = hero[G.mag], idx = hero[G.idx];
            const base = G.list[idx] || G.list[0];
            const head = '<div style="font-size:10px;letter-spacing:.12em;color:#fbbf24;margin-bottom:4px">CURRENTLY EQUIPPED</div>';
            const body = mag ? magicItemTip(mag, hero) : (idx < 0 ? tipBox(kind === 'w' ? 'Bare Hands' : (kind === 'h' ? 'Bare Head' : (kind === 's' ? 'No Shield' : 'No Clothes')), 'Nothing equipped', [], kind === 'w' ? 'Fists: 1d2 damage.' : (kind === 'h' ? 'Nothing on thy head.' : (kind === 's' ? 'No shield in thy off-hand.' : 'Unclothed: AC 9.'))) : plainGearTip(kind, base, hero));
            return head + body;
        }
        // Ctrl+click on gear: a window showing how it would look on the champion
        function openGearPreview(kind, baseIdx, magic) {
            const hero = barberHero(); if (!hero) return;
            const modal = document.getElementById('gear-preview-modal');
            const item = GEAR[kind].list[baseIdx];
            const rar = magic ? ((magic.pre && magic.suf) ? 2 : 1) : 0;
            const now = heroLook(hero);
            const vr = magic ? itemVariant(magic) : 0;
            const after = Object.assign({}, now, kind === 'w' ? { w: baseIdx, wr: rar, wv: vr, nw: false } : (kind === 'h' ? { hd: baseIdx, hh: false } : (kind === 's' ? { sh: baseIdx, sr: rar, sv: vr } : { a: baseIdx, ar: rar, av: vr, nc: false })));
            document.getElementById('gp-title').innerHTML = magic ? itemHtml(magic) : item.name;
            const ok = item.classes.includes(hero.cls) || hero.debug || (magic && canUseItem(hero, magic));
            document.getElementById('gp-note').innerHTML = ok ? `<span class="text-slate-400">${kind === 'w' ? weaponLabel(item) : (kind === 'h' ? ('AC +' + item.ac + (item.mp ? ', +' + item.mp + ' MP' : '')) : (kind === 's' ? ('AC +' + item.ac) : armorLabel(item)))}</span>` : `<span style="color:#fb7185">${hero.cls}s cannot use this.</span>`;
            const draw = (id, look) => { const c = document.getElementById(id), g = c.getContext('2d'); g.clearRect(0, 0, c.width, c.height); g.fillStyle = 'rgba(2,6,23,.55)'; g.fillRect(0, 0, c.width, c.height); drawHeroCharacterVector(g, -20, 4, 200, hero.cls, false, hero.race, look); };
            draw('gp-now', now); draw('gp-after', after);
            modal.classList.remove('hidden');
            const close = () => { modal.classList.add('hidden'); window.removeEventListener('keydown', key, true); };
            const key = (e) => { if (e.key === 'Escape' || e.key === 'Enter' || e.key === ' ') { e.preventDefault(); e.stopPropagation(); close(); } };
            window.addEventListener('keydown', key, true);
            document.getElementById('gp-close').onclick = close;
            modal.onclick = (e) => { if (e.target === modal) close(); };
        }
        function magicItemTip(m, hero) {
            const base = itemBase(m);
            const rows = [['Base', base.name], ['Stats', itemStatLine(m)], ['Value', `sells for ${Math.floor(itemValue(m) * 0.5)} gold`], ['Classes', base.classes.join(', ')]];
            const aff = itemAffixes(m).map(a => `✦ ${a.txt}`).join('<br>');
            const warn = hero && !canUseItem(hero, m) ? `<br><span style="color:#fb7185">${hero.cls}s cannot use this.</span>` : '';
            return tipBox(`<span style="color:${itemColor(m)}">${itemName(m)}</span>`, `${itemRarity(m) === 'rare' ? 'Rare' : 'Magic'} ${GEAR[m.k].noun}`, rows, `✦ ${m.k === 'h' ? '+' + Math.ceil(m.p / 2) + ' AC' : '+' + m.p + ' ' + (m.k === 'w' ? 'to hit & damage' : 'AC')}${aff ? '<br>' + aff : ''}${warn}`, null, gearIcon(m.k, base, m));
        }
        function heroTip(h) {
            const w = heroWeapon(h), a = heroArmor(h), c = CLASSES[h.cls] || CLASSES.Fighter;
            const atk = heroAttackBonus(h, w);
            const rows = [
                ['Hit points', `${h.hp} / ${h.maxHp}`, h.hp <= 0 ? '#f87171' : '#6ee7b7'],
                h.maxMp > 0 ? ['Mana', `${h.mp} / ${h.maxMp}`, '#7dd3fc'] : null,
                ['Armour class', `${heroAC(h)}`],
                ['Attack', `${atk >= 0 ? '+' : ''}${atk} to hit, ${w.dice}${weaponAbilMod(h, w) ? (weaponAbilMod(h, w) > 0 ? '+' : '') + weaponAbilMod(h, w) : ''}`],
                ['STR / DEX', `${h.str} / ${h.dex}`], ['INT / WIS', `${h.int} / ${h.wis}`],
                ['Experience', h.lvl >= MAX_LEVEL ? `${h.xp} (max level)` : `${h.xp} / ${xpToNext(h.lvl)}`],
                ['Weapon', h.wMag ? `<span style="color:${itemColor(h.wMag)}">${w.name}</span>` : w.name],
                ['Shield', h.sMag ? `<span style="color:${itemColor(h.sMag)}">${itemName(h.sMag)}</span>` : (h.shieldIdx >= 0 ? SHIELDS[h.shieldIdx].name : 'none'), (h.shieldIdx >= 0 || h.sMag) ? null : '#94a3b8'],
                ['Armour', h.aMag ? `<span style="color:${itemColor(h.aMag)}">${a.name}</span>` : a.name],
                ['Boots', h.boots ? 'Swamp Boots' : 'none (marsh poison!)', h.boots ? null : '#94a3b8']
            ];
            const st = [];
            if (h.hp <= 0) st.push('<span style="color:#f87171">Fallen - needs Resurrect</span>');
            if (h.poisoned && h.hp > 0) st.push('<span style="color:#a3e635">☠ Poisoned: loses HP every second</span>');
            if (h.prot && state.mode === 'COMBAT') st.push(`<span style="color:#7dd3fc">Protected: +${h.prot.ac} AC, +${h.prot.hit} hit (${h.prot.rounds} rounds)</span>`);
            if (h.debug) st.push('<span style="color:#f0abfc">◆ Playtest hero</span>');
            const known = getKnownSpells(h).length;
            if (known) st.push(`Knows ${known} spell${known > 1 ? 's' : ''}.`);
            return tipBox(h.name, `Lv ${h.lvl} ${h.race} ${h.cls} • d${c.hd} hit die`, rows, st.join('<br>'), 'Click for full stats & gear', `<span class="it-ico" style="--c:251,191,36">${icon(CLASS_GLYPH[h.cls] || 'star')}</span>`);
        }
        // a short, stable code for a settlement's seed (shown in the location tooltip)
        function townSeedLabel(seed) { let h = 2166136261; for (let i = 0; i < seed.length; i++) h = Math.imul(h ^ seed.charCodeAt(i), 16777619); return (h >>> 0).toString(16).toUpperCase().padStart(8, '0'); }
        function hudTips() {
            const t = getTimeOfDayInfo(), wk = weatherKind();
            const set = (id, html) => { const el = document.getElementById(id); if (el) el.dataset.tip = html; };
            set('hud-mode', tipBox('Location', state.mode, state.mode === 'TOWN' && state.town.seed ? [['Town seed', townSeedLabel(state.town.seed)]] : null, { OVERWORLD: 'Travelling the open realm. A game hour lasts 2 real minutes, whether you walk or not.', TOWN: 'Inside a settlement. The world clock runs here too; a bed at the inn restores everyone (1 minute of rest).', DUNGEON: 'Deep below ground. Monsters lurk in the dark.', COMBAT: 'Tactical battle - heroes act in turn, then the foes.' }[state.mode] || ''));
            set('hud-local', tipBox('Your local time', new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), null, 'The clock of thy own computer. The sun-icon clock beside it shows the time in the game world (one game hour = 2 real minutes).'));
            set('hud-time', tipBox(`In-game: Day ${t.day}, ${t.hourStr}`, t.label, [['Sight', `${t.los} tiles`], ['Weather', wk === 'clear' ? 'clear skies' : (wk === 'storm' ? 'thunderstorm' : 'rain'), wk === 'clear' ? null : '#7dd3fc']],
                wk === 'clear' ? 'Night shortens sight; a Light spell widens it.' : (wk === 'storm' ? 'Thunderstorm: sight -2 and -2 to hit (missiles -3) in battles under the open sky.' : 'Rain: sight -1 and -1 to hit (missiles -2) in battles under the open sky.')));
            const { astra, luna } = getLunarPhases(state.turns);
            const g = state.overworld.moongates[luna];
            set('hud-moons', tipBox('The Twin Moons', 'Astra & Luna', [['Astra', MOON_PHASE_NAMES[astra]], ['Luna', MOON_PHASE_NAMES[luna]], ['Moongates lead to', g ? g.name : '-']], 'Luna\'s phase decides where every Moongate sends you.'));
            set('hud-rations', tipBox('Rations', String(state.inventory.rations || 0), [['Per camp', '1 ration']], 'Pitching camp [R] uses up one ration, even if the rest is cut short. Buy more from a provisioner, or conjure them with Create Food.'));
            set('hud-gold', tipBox('Gold', `${state.gold} coins`, [['Potions', `${potTotal()}`], ['Magic items in bag', `${(state.inventory.magic || []).length}`]], 'Spend it on gear, rooms, healing, swamp boots and ship deeds.'));
            const ti = document.getElementById('stat-time-ico');
            const glyph = wk === 'storm' ? 'storm' : (wk === 'rain' ? 'rain' : (t.label === 'Night' ? 'moon' : (t.label === 'Day' ? 'sun' : 'sunrise')));
            if (ti && ti.dataset.g !== glyph) { ti.innerHTML = icon(glyph); ti.dataset.g = glyph; }
        }
        // one floating tooltip for every element with data-tip / data-tip-cmd
        (function setupTooltips() {
            let cur = null, tipEl = null, tip2 = null;
            const place = (e) => {
                if (!tipEl) return;
                const pad = 14, r = tipEl.getBoundingClientRect();
                let x = e.clientX + pad, y = e.clientY + pad;
                if (x + r.width > window.innerWidth - 6) x = e.clientX - r.width - pad;
                if (y + r.height > window.innerHeight - 6) y = e.clientY - r.height - pad;
                tipEl.style.left = Math.max(4, x) + 'px';
                tipEl.style.top = Math.max(4, y) + 'px';
                if (tip2 && tip2.classList.contains('on')) {          // the comparison tooltip sits beside the first
                    const r2 = tip2.getBoundingClientRect(), left = Math.max(4, x), w1 = r.width;
                    let x2 = left + w1 + 8;
                    if (x2 + r2.width > window.innerWidth - 6) x2 = left - r2.width - 8;
                    tip2.style.left = Math.max(4, x2) + 'px';
                    tip2.style.top = Math.max(4, Math.min(y, window.innerHeight - r2.height - 6)) + 'px';
                }
            };
            document.addEventListener('mouseover', (e) => {
                tipEl = tipEl || document.getElementById('ui-tip');
                if (!tipEl) return;
                const el = e.target.closest && e.target.closest('[data-tip],[data-tip-cmd]');
                if (el === cur) return;
                cur = el;
                if (!el) { tipEl.classList.remove('on'); if (tip2) tip2.classList.remove('on'); return; }
                const html = el.dataset.tipCmd ? cmdTip(el.dataset.tipCmd) : el.dataset.tip;
                if (!html) { tipEl.classList.remove('on'); if (tip2) tip2.classList.remove('on'); return; }
                tipEl.innerHTML = html;
                tipEl.classList.add('on');
                tip2 = tip2 || document.getElementById('ui-tip2');
                if (tip2) { if (el.dataset.tip2) { tip2.innerHTML = el.dataset.tip2; tip2.classList.add('on'); } else tip2.classList.remove('on'); }
                place(e);
            });
            document.addEventListener('mousemove', (e) => { if (cur) place(e); });
            const hide = () => { if (tipEl) tipEl.classList.remove('on'); if (tip2) tip2.classList.remove('on'); cur = null; };
            document.addEventListener('mousedown', hide);
            document.addEventListener('keydown', hide, true);
            // a modal opening over the hovered element, or the element being re-rendered, must not leave a stale tooltip
            setInterval(() => { if (cur && (!cur.isConnected || cur.offsetParent === null)) hide(); }, 250);
            document.addEventListener('mousemove', (e) => {
                if (!cur) return;
                const under = document.elementFromPoint(e.clientX, e.clientY);
                if (!under || !cur.contains(under)) hide();
            });
        })();

        // ===================== UI: LOOT POPUP =====================
