        const lootQueue = [];
        function showLoot(title, entries, sub, iconGlyph) {
            lootQueue.push({ title, entries, sub, iconGlyph });
            if (!state.lootPopup) nextLoot();
        }
        function nextLoot() {
            const L = lootQueue.shift();
            const modal = document.getElementById('loot-modal');
            if (!L || !modal) { state.lootPopup = false; if (modal) modal.classList.add('hidden'); return; }
            state.lootPopup = true;
            document.getElementById('loot-title').textContent = L.title;
            document.getElementById('loot-sub').textContent = L.sub || '';
            document.getElementById('loot-icon').innerHTML = icon(L.iconGlyph || 'chest');
            const list = document.getElementById('loot-list');
            list.innerHTML = L.entries.map(en => `<div class="loot-row"${en.tip ? ' ' + tipAttr(en.tip) : ''}>${en.icon}<div style="min-width:0"><div style="font-weight:700;font-size:12.5px">${en.title}</div>${en.sub ? `<div style="font-size:10.5px;color:#94a3b8">${en.sub}</div>` : ''}</div></div>`).join('');
            modal.classList.remove('hidden');
            const box = document.getElementById('loot-box');
            if (box) { box.style.animation = 'none'; void box.offsetWidth; box.style.animation = ''; }
            sfx.play('gold');
        }
        function closeLoot() { nextLoot(); updateUI(); }
