                    const lo = chordNotes(ch, 2), mid = chordNotes(ch, 3), hi = chordNotes(ch, 4);
                    // bass
                    if (def.bass === 'march') [[0, 2, lo[0]], [2, 1, lo[0]], [3, 1, lo[2]], [4, 2, lo[0] * 2], [6, 2, lo[2]]].forEach(([o, d, f]) => ev.push({ v: 'bass', t: b0 + o, d, f }));
                    else if (def.bass === 'swell') [[0, 3, lo[0]], [3, 3, lo[2]]].forEach(([o, d, f]) => ev.push({ v: 'bass', t: b0 + o, d, f }));
                    else if (def.bass === 'waltz') ev.push({ v: 'bass', t: b0, d: 2, f: lo[0] });
                    else if (def.bass === 'drone') ev.push({ v: 'bass', t: b0, d: def.bar, f: lo[0] });
                    else if (def.bass === 'jig') [[0, 1.5, lo[0]], [3, 1.5, lo[2]]].forEach(([o, d, f]) => ev.push({ v: 'bass', t: b0 + o, d, f }));
                    else if (def.bass === 'epic') [[0, 4, lo[0]], [4, 4, lo[2]]].forEach(([o, d, f]) => ev.push({ v: 'bass', t: b0 + o, d, f }));
                    else if (def.bass === 'drive') for (let k = 0; k < 8; k++) ev.push({ v: 'bass', t: b0 + k, d: 1, f: (k === 2 || k === 6) ? lo[0] * 2 : (k === 7 ? lo[2] : lo[0]) });
                    // harmony
                    if (def.arp === 'up') [mid[0], mid[1], mid[2], hi[0], mid[2], mid[1], mid[0], mid[1]].forEach((f, k) => ev.push({ v: 'arp', t: b0 + k, d: 1, f }));
                    else if (def.arp === 'wave') [mid[0], mid[2], hi[0], hi[1], hi[0], mid[2]].forEach((f, k) => ev.push({ v: 'arp', t: b0 + k, d: 1, f }));
                    else if (def.arp === 'strum') [2, 4].forEach(o => mid.forEach((f, k) => ev.push({ v: 'arp', t: b0 + o + k * 0.06, d: 1.6, f })));
                    else if (def.arp === 'stab') [2, 6].forEach(o => mid.forEach(f => ev.push({ v: 'arp', t: b0 + o, d: 0.7, f })));
                    else if (def.arp === 'offbeat') [1, 2, 4, 5].forEach(o => mid.forEach((f, k) => ev.push({ v: 'arp', t: b0 + o + k * 0.04, d: 0.7, f })));
                    else if (def.arp === 'pad') {                      // chords held for the whole bar
                        mid.concat([hi[0]]).forEach(f => ev.push({ v: 'pad', t: b0, d: def.bar, f }));
                        if (def.pad === 'choir') [2, 5].forEach((o, k) => ev.push({ v: 'bell', t: b0 + o, d: 3, f: hi[k % 3] * 2 }));
                    }
