                    const hp = c.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = e.soft ? 5000 : 1800;
                    const g = c.createGain(); g.gain.setValueAtTime(e.soft ? 0.05 : 0.09, at); g.gain.exponentialRampToValueAtTime(0.0005, at + (e.soft ? 0.08 : 0.12));
                    s.connect(hp); hp.connect(g); g.connect(out); s.start(at, Math.random()); s.stop(at + 0.15);
