            panel.classList.remove('hidden');
            const v = document.getElementById('jb-vol'); if (v) { v.value = Math.round(((sfx.vol && sfx.vol.music) != null ? sfx.vol.music : 1) * 100); document.getElementById('jb-vol-val').textContent = v.value + '%'; }
