            REAL_MOUNTAIN_CHAINS.forEach(m => { m.x1 *= WS; m.y1 *= WS; m.x2 *= WS; m.y2 *= WS; m.radius *= WS * 0.62; });
            WORLD_RIVERS.forEach(r => r.pts.forEach(p => { p[0] *= WS; p[1] *= WS; }));
