                    let c = 1 + tlHash(x * 7 + 3, y * 13 + 5) * 1.3;             // meandering
                    if (getWorldTile(x, y) === TILE.MOUNTAIN) c += 2.5;          // water seeks the valleys
                    c += otherRiverNear(x, y) * 8;                               // never run alongside another river
                    let selfN = 0;
