                    const leg = riverLeg(cur.x, cur.y, tgt.x, tgt.y, (x, y) => trunk.has(owIdx(x, y)) && getWorldTile(x, y) === TILE.RIVER, (x, y) => blocked(x, y) || (otherRiverNear(x, y) > 0 && Math.abs(x - tgt.x) + Math.abs(y - tgt.y) > 2), cost, 16);
