            k.rect(.34, .68, .32, .035, '#57300f'); k.rect(.47, .675, .06, .045, '#d6d3d1', O);
            // arms
            k.arm(.35, .44, .27, .58, '#94a3b8'); k.arm(.65, .44, .79, .50, '#94a3b8');
            // round shield (left)
