            vgEll(ctx, s * .20, s * .56, s * .15, s * .15, null, '#b0b7c3', lw * 1.6);
            vgPath(ctx, s, [[.20, .43], [.20, .69]], 'rgba(60,25,5,.55)', lw); vgPath(ctx, s, [[.07, .56], [.33, .56]], 'rgba(60,25,5,.55)', lw);
            vgBall(ctx, s * .20, s * .56, s * .04, '#f1f5f9', '#64748b', O, lw * .8);
