            vgPoly(ctx, s, [[.38, .20], [.40, .09], [.50, .06], [.60, .09], [.62, .20]], vgLin(ctx, s * .38, 0, s * .62, 0, [[0, '#f1f5f9'], [0.5, '#94a3b8'], [1, '#475569']]), O, lw);
