                        for (let i = 0; i < 6; i++) { const x = s * (0.1 + rng() * 0.8), y = s * (0.3 + rng() * 0.65); ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + (rng() - 0.5) * s * 0.06, y - s * (0.07 + rng() * 0.07)); ctx.stroke(); }
