                    ctx.beginPath(); ctx.moveTo(s * 0.34, s * 0.93); ctx.lineTo(s * 0.38, s * 0.8); ctx.lineTo(s * 0.62, s * 0.8); ctx.lineTo(s * 0.66, s * 0.93); ctx.closePath(); ctx.fill();
                    ctx.save();
                    ctx.beginPath(); ctx.rect(x0, y0, x1 - x0, y1 - y0); ctx.clip();
                    ctx.fillStyle = '#f8fafc'; ctx.fillRect(x0, y0, x1 - x0, y1 - y0);
                    const shift = (phase / (Math.PI * 2)) * per;
                    for (let i = -2; i < 7; i++) {
                        const y = y0 + i * per + shift;
                        ctx.fillStyle = '#dc2626';
                        ctx.beginPath(); ctx.moveTo(x0, y); ctx.lineTo(x1, y - slope); ctx.lineTo(x1, y - slope + per * 0.34); ctx.lineTo(x0, y + per * 0.34); ctx.closePath(); ctx.fill();
                        ctx.fillStyle = '#2563eb';
                        const y2 = y + per * 0.5;
                        ctx.beginPath(); ctx.moveTo(x0, y2); ctx.lineTo(x1, y2 - slope); ctx.lineTo(x1, y2 - slope + per * 0.34); ctx.lineTo(x0, y2 + per * 0.34); ctx.closePath(); ctx.fill();
                    }
                    ctx.fillStyle = tlGrad(ctx, x0, 0, x1, 0, [[0, 'rgba(0,0,0,0.28)'], [0.35, 'rgba(255,255,255,0.35)'], [0.55, 'rgba(255,255,255,0)'], [1, 'rgba(0,0,0,0.35)']]);
                    ctx.fillRect(x0, y0, x1 - x0, y1 - y0);
                    ctx.restore();
                    ctx.strokeStyle = 'rgba(30,20,10,0.8)'; ctx.lineWidth = Math.max(0.8, s * 0.022); ctx.strokeRect(x0, y0, x1 - x0, y1 - y0);
