                    const sway = Math.sin(phase) * s * 0.008;
                    ctx.strokeStyle = '#3a2410'; ctx.lineWidth = Math.max(1, s * 0.035);
                    ctx.beginPath(); ctx.moveTo(s * 0.42, s * 0.88); ctx.lineTo(s * 0.44, s * 0.68); ctx.moveTo(s * 0.58, s * 0.88); ctx.lineTo(s * 0.56, s * 0.68); ctx.stroke();
                    const blobs = [[0.28, 0.62, 0.2], [0.72, 0.62, 0.2], [0.5, 0.7, 0.22], [0.36, 0.44, 0.2], [0.64, 0.44, 0.2], [0.5, 0.34, 0.2], [0.5, 0.54, 0.25]];
