                    g.strokeStyle = gr; g.lineWidth = cs * 0.34; g.lineCap = 'round'; g.beginPath(); g.moveTo(tx, ty); g.lineTo(x, y); g.stroke();
                    fxGlowAt(g, x, y, cs * 0.7, '255,140,40', 0.9);
                    g.restore();
