                    for (let i = 0; i < 6; i++) {
                        const a = p * 6 + i * 1.05, r = cs * 0.46;
                        fxSparkle(g, c.x + Math.cos(a) * r, c.y + Math.sin(a) * r * 0.55 - cs * 0.1, 2.4, '170,140,255', Math.sin(Math.PI * p));
                    }
                    fxGlowAt(g, c.x, c.y, cs * 0.7, '120,100,255', 0.3 * Math.sin(Math.PI * p));
                    g.restore();
                    g.font = `bold ${Math.round(cs * 0.3)}px 'JetBrains Mono'`; g.textAlign = 'center';
                    for (let i = 0; i < 3; i++) {
                        const q = (p * 1.6 + i * 0.28) % 1;
                        g.fillStyle = `rgba(191,219,254,${Math.sin(Math.PI * q) * Math.min(1, (1 - p) * 3)})`;
                        g.fillText('Z', c.x + Math.sin(q * 6 + i * 2) * cs * 0.22 + (i - 1) * cs * 0.18, c.y - cs * 0.1 - q * cs * 0.8);
                    }
