                    g.beginPath(); g.arc(x - r * 0.4, y - r * 0.05, r * 0.28, 0, 7); g.arc(x + r * 0.4, y - r * 0.05, r * 0.28, 0, 7); g.fill();
                    g.beginPath(); g.moveTo(x, y + r * 0.25); g.lineTo(x - r * 0.12, y + r * 0.55); g.lineTo(x + r * 0.12, y + r * 0.55); g.closePath(); g.fill();
                    g.strokeStyle = `rgba(15,0,25,${a})`; g.lineWidth = 1;
